// insert all nums as 31-bit paths first
int maxXorQuery(int x){
    Node* cur = root; int ans = 0;
    for (int b = 30; b >= 0; b--) {
        int bit = (x >> b) & 1;
        int want = 1 - bit;              // opposite!
        if (cur->ch[want]) { ans |= 1 << b; cur = cur->ch[want]; }
        else                  cur = cur->ch[bit];
    }
    return ans;
}
